const photo={art:'onion120-v1',title:'Onion-cell photograph',sourceTitle:'Living cells of onion epidermis',caption:'This is a real micrograph of a surface layer from onion tissue, shared by Berkshire Community College Bioscience Image Library. Describe the long compartments and the borders between them. Which features can you point to, and which names would need more evidence?',alt:'Microscope photograph of long, adjoining onion surface cells with dark boundaries and small rounded features. Not every feature is equally sharp.',credit:'Berkshire Community College Bioscience Image Library (bccoer), 2017.',license:'CC0 1.0 Universal Public Domain Dedication.',captureLabel:'Source-reported capture: 120×',notice:'The source labels the capture 120×. This photograph has been resized for the screen; its displayed size is not calibrated magnification. Enlarging it uses the same recorded pixels and cannot reveal new captured detail. It is not the practice slide or a live microscope view.',zooms:[1,2,4]};
