 const marks=arts.map((art,i)=>({id:`${prefix}${i+1}`,label:`Practice mark ${i+1}`,art,x:[90,200,310][i%3],y:[90,200,310][Math.floor(i/3)],size:sizes[i]}));
 const target=marks[targetIndex];
 return {v:1,model:'lens-bench-v1',id,title,context:'The librarian needs a clear view for the town collection. Find the marked practice pattern before choosing a closer view.',notice,returnQuestion:'Your kept practice view is a model. Compare it with a Cell Studio illustration. What does each drawing let you explain, and what would a real slide help you check?',photoQuestion:'In the photograph, which borders or repeated shapes can you point to? Compare those pixels with the parts chosen in Cell Studio. Which details are drawn to explain an idea rather than shown by this photograph?',annotation:'The blue dashed ring is a game marker added to the drawing. It is not part of a specimen, and it stays sharp while our practice picture blurs.',world:{width:400,height:400,baseDiameter:400,baseObjectiveId:'o4',center:{x:200,y:200}},eyepiece:10,objectives:[{id:'o4',label:'4× objective',power:4},{id:'o10',label:'10× objective',power:10},{id:'o40',label:'40× objective',power:40}],marks,targetId:target.id,focus:[{id:'f0',label:'Very soft',blur:3},{id:'f1',label:'Soft',blur:1},{id:'f2',label:'Clear',blur:0},{id:'f3',label:'Soft',blur:1},{id:'f4',label:'Very soft',blur:3}],initialFocusId:'f1',teaching:teaching.map((text,i)=>({text,view:{objectiveId:['o4','o4','o10','o40','o40','o40','o10'][i],focusId:i===4?'f0':'f2',center:i===0?{x:200,y:200}:{x:target.x,y:target.y}}})),photo:structuredClone(photo)};
